def main():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    for person_id, bio in BIOS.items():
        cur.execute("SELECT person_id FROM persons WHERE person_id = ?", (person_id,))
        if not cur.fetchone():
            print(f"WARNING: person_id not found: {person_id}")
            continue
        cur.execute("UPDATE persons SET bio_html = ? WHERE person_id = ?", (bio, person_id))
        word_count = len(bio.split())
        print(f"Updated {person_id}: {word_count} words")
    conn.commit()
    conn.close()
    print("Bio batch 1 complete.")


if __name__ == "__main__":
    main()
